/// <summary>
/// Bug 347690: [MS] E2E - CB201 - Non-Editable fields are Editable when Rebate Deal is Active - MS SR#2603190030005077
/// MS private fix
/// </summary>
[ExtensionOf(formDataSourceStr(TAMRebateDeal, TAMRebateDate))]
internal final class METTAMRebateDeal_TAMRebateDate_Extension
{
}

Method.Source:
private boolean rebateDateHasDateTrans(TAMRebateDate rebateDate)
{
    if (!rebateDate.RecId)
    {
        return false;
    }

    TAMRebateDateTrans rebateDateTrans;
    select firstonly RecId from rebateDateTrans
            where rebateDateTrans.RebateDateRecId == rebateDate.RecId;

    return rebateDateTrans.RecId != 0;
}

public int active()
{
    int ret = next active();

    FormDataSource TAMRebateDeal_ds = this.formRun().dataSource(tablestr(TAMRebateDeal));
    TAMRebateDeal  rebateDeal = TAMRebateDeal_ds.cursor();

    boolean shouldShowGUPUI = TAMRebateDealGUPExtensionHelper::shouldShowGUPUI(this.formRun());

    if (shouldShowGUPUI)
    {
        FormDataSource TAMRebateDate_ds = this.formRun().dataSource(tablestr(TAMRebateDate));

        TAMRebateDate rebateDate = TAMRebateDate_ds.cursor();
        boolean rebateDateEditable = rebateDeal.RebateActive == NoYes::No && !this.rebateDateHasDateTrans(rebateDate);
        TAMRebateDate_ds.object(fieldNum(TAMRebateDate, RebateToDate)).allowEdit(rebateDateEditable);
        TAMRebateDate_ds.object(fieldNum(TAMRebateDate, RebateToDate)).skip(!rebateDateEditable);
    }

    return ret;
}
